import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import '@kerfjs/ui/layout.css';
import './workspace-navigation.css';

const HomeIcon = () => <svg aria-hidden="true" viewBox="0 0 16 16"><path d="M2 8 8 2l6 6v6H9v-4H7v4H2Z" /></svg>;

export function WorkspaceNavigation() {
  return (
    <nav className="workspace-nav kui-sidebar" aria-label="Workspace navigation">
      <section className="kui-sidebar-section">
        <MenuHeader>Workspace</MenuHeader>
        <MenuItem href="/home" icon={<HomeIcon />} selected aria-current="page">Home</MenuItem>
        <MenuItem href="/activity">Activity</MenuItem>
        <MenuItem href="/archive" disabled>Archive unavailable</MenuItem>
      </section>
      <section className="kui-sidebar-section">
        <MenuHeader>Projects</MenuHeader>
        <MenuItem href="/projects/alpha">Alpha</MenuItem>
        <MenuItem href="/projects/beta">Beta</MenuItem>
      </section>
      <section className="workspace-summary kui-sidebar-surface" aria-labelledby="workspace-summary-title">
        <h2 id="workspace-summary-title">Team workspace</h2>
        <p>12 members · 4 active projects</p>
      </section>
      <div className="nav-footer" aria-label="Workspace actions">
        <button type="button">Settings</button>
        <button type="button">Help</button>
      </div>
    </nav>
  );
}

