.workspace-nav { display: flex; flex-direction: column; min-block-size: 100%; }
.workspace-summary { padding: var(--kui-space-surface); }
.workspace-summary h2 { font: inherit; font-weight: 600; margin: 0; }
.workspace-summary p { margin-block: var(--kui-space-control) 0; }
.nav-footer { display: flex; flex-wrap: wrap; gap: var(--kui-space-control); margin-block-start: auto; }
.nav-footer button { min-block-size: 2.75rem; }
